questionvariables.text:
/* [low, high, an odd composite strictly inside the range] */
plist: [[3, 25, 9], [5, 30, 15], [3, 20, 9], [7, 31, 21], [5, 23, 15], [11, 37, 25]];
ppick: rand(plist);
lo: ppick[1];
hi: ppick[2];
oddc: ppick[3];
ta1: setify(sublist(makelist(jj, jj, lo + 1, hi - 1), primep));
endp: setify(sublist([lo, hi], primep));
pmax: lmax(listify(ta1));
ptable: makelist([pp, (pp - 1)*(pp + 1), (pp - 1)*(pp + 1)/12], pp, listify(ta1));
/* Validators run with simp:false, where -1 and 6/2 are not yet integers, so simplify first. */
validate_intset(ex) := block([vv], vv: ev(ex, simp), if not(setp(vv)) then "Type a set in curly brackets, for example {5, 6}, or {} for no values."
  else if not(every(integerp, listify(vv))) then "Type whole numbers only." else "");
s_assert(every(lambda([pp], is(mod((pp - 1)*(pp + 1), 12) = 0)), listify(ta1)), true);
s_assert(is(endp # {} and not(primep(oddc)) and oddc > lo and oddc < hi), true);

feedbackvariables.text:
sl: listify(ans1);
outside: sublist(sl, lambda([xx], xx <= lo or xx >= hi));
nonprime: sublist(sl, lambda([xx], not(primep(xx))));
